UPDATE document_definition_versions
SET schema_json = '{"code":"CANADA_PERMANENT_RESIDENT","country":"CA","documentType":"RESIDENCE_PERMIT","version":"2015","side":"FRONT","mrzFormat":"NONE","reading":"Canada permanent resident card front, issued by the Government of Canada. The printed title is Permanent Resident Card or Carte de résident permanent. Use CANADA_PERMANENT_RESIDENT only when that title is visible. A hospital card, a university card, a health card, or any other card is not this document.","fields":[{"name":"lastName","type":"NAME","required":true,"normalizer":"ICAO_NAME","hint":"surname on the Name/Nom line; it may contain two words"},{"name":"firstName","type":"NAME","required":true,"normalizer":"ICAO_NAME","hint":"given names on the line under the surname"},{"name":"documentNumber","type":"DOCUMENT_NUMBER","required":true,"hint":"labeled ID No; this is not the PD number on the back"},{"name":"dateOfBirth","type":"DATE","required":true,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"labeled Date of birth; the card prints a bilingual date such as 09 APR /AVR 92; write yyyy-MM-dd, and a past year 92 is 1992"},{"name":"expirationDate","type":"DATE","required":true,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"labeled Expiry; write yyyy-MM-dd, and a year 30 is 2030"},{"name":"sex","type":"SEX","required":false,"hint":"labeled Sex"},{"name":"nationality","type":"NATIONALITY","required":false,"hint":"labeled Nationality, alpha-3 such as CMR"}],"rules":[]}'
